1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's canonical region ("locality"). The postcode is preferred:
7	 * a 4-digit postcode is matched against each region's inclusive range first, and
8	 * only when the postcode is absent or in no known range does derivation fall back
9	 * to a fixed city-to-region table. Kept as a plain utility (rather than a mapper
10	 * method) so MapStruct does not treat it as an implicit {@code String -> String}
11	 * mapping.
12	 */
13	public final class Localities {
14	
15	    /** City -> canonical region. Anything not listed derives {@link #UNKNOWN}. */
16	    private static final Map<String, String> CITY_REGION = Map.of(
17	        "Sydney", "NSW",
18	        "Melbourne", "VIC",
19	        "Brisbane", "QLD");
20	
21	    /** Region -> inclusive 4-digit postcode range {low, high}. */
22	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
23	        "NSW", new int[] {2000, 2099},
24	        "VIC", new int[] {3000, 3099},
25	        "QLD", new int[] {4000, 4099});
26	
27	    /** Region returned for a city that is absent from {@link #CITY_REGION}. */
28	    public static final String UNKNOWN = "UNKNOWN";
29	
30	    private Localities() {
31	    }
32	
33	    /**
34	     * Returns the canonical region for {@code city} from the fixed table
35	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
36	     * or {@code "UNKNOWN"} when the city is {@code null} or not in the table.
37	     *
38	     * @param city the owner's city
39	     * @return the canonical region string, or {@code "UNKNOWN"} when unknown
40	     */
41	    public static String forCity(String city) {
42	        if (city == null) {
43	            return UNKNOWN;
44	        }
45	        return CITY_REGION.getOrDefault(city, UNKNOWN);
46	    }
47	
48	    /**
49	     * Returns the canonical region, preferring the {@code postcode}: it is matched
50	     * against each region's inclusive postcode range first (NSW 2000-2099,
51	     * VIC 3000-3099, QLD 4000-4099). Only when the postcode is {@code null},
