51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        String normalizedAddress = normalizeAddress(owner.getAddress());
108	        if (normalizedAddress.isEmpty()) {
109	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
110	                "Address must not be blank after normalization");
111	        }
112	        owner.setAddress(normalizedAddress);
113	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
114	        owner.setTelephone(normalizedTelephone);
115	        owner.setEmail(normalizeEmail(owner.getEmail()));
116	        validatePostcode(owner.getPostcode(), owner.getCity());
117	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
118	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
119	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
120	        owner.setRegistrationDate(businessDate);
121	        long createdToday = this.clinicService.findAllOwners().stream()
122	            .map(Owner::getRegistrationDate)
123	            .filter(businessDate::equals)
124	            .count();
125	        if (createdToday >= 100) {
126	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
127	                "The maximum number of owners for today has already been reached");
128	        }
129	        owner.setBulkSignupWarning(createdToday > 80);
130	        String lastNameKey = normalizeForHousehold(owner.getLastName());
131	        String addressKey = normalizeForHousehold(owner.getAddress());
132	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
133	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(lastNameKey)
134	                && normalizeForHousehold(existing.getAddress()).equals(addressKey))
135	            .toList();
136	        String householdId = null;
137	        if (!householdMembers.isEmpty() && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
138	            householdId = householdId(lastNameKey, addressKey);
139	            owner.setHouseholdId(householdId);
140	        }
141	        // All duplicate detection is now expressed through the single derived identityKey
142	        // (telephone|email|householdId); a new owner is rejected only when its whole key matches.
143	        String identityKey = owner.getIdentityKey();
144	        boolean identityInUse = this.clinicService.findAllOwners().stream()
145	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
146	        if (identityInUse) {
147	            throw new ResponseStatusException(HttpStatus.CONFLICT,
148	                "An owner with this identity already exists");
149	        }
150	        if (householdId != null) {
151	            for (Owner member : householdMembers) {
152	                if (!householdId.equals(member.getHouseholdId())) {
153	                    member.setHouseholdId(householdId);
154	                    this.clinicService.saveOwner(member);
155	                }
156	            }
157	        }
158	        String cityKey = normalizeForHousehold(owner.getCity());
159	        long cityCount = this.clinicService.findAllOwners().stream()
160	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
161	            .count();
162	        if (cityCount >= 50) {
163	            throw new ResponseStatusException(HttpStatus.CONFLICT,
164	                "This city already has the maximum number of owners");
165	        }
166	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
167	        owner.setHouseholdSize(householdMembers.size() + 1);
168	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
169	        this.clinicService.saveOwner(owner);
170	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
171	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
172	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
173	        headers.setLocation(UriComponentsBuilder.newInstance()
174	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
175	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
176	    }
177	
178	    /**
179	     * Rolls a registration date forward to a business day. When {@code date} falls on a Saturday or
180	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
181	     * to the effective registration date (whether supplied in the request or defaulted to the server
182	     * date) so that every stored {@code registrationDate}, and any value derived from it, lands on a
183	     * business day.
184	     *
185	     * @param date the effective registration date
186	     * @return the same date if it is a weekday, otherwise the following Monday
187	     */
188	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
189	        return switch (date.getDayOfWeek()) {
190	            case SATURDAY -> date.plusDays(2);
191	            case SUNDAY -> date.plusDays(1);
192	            default -> date;
193	        };
194	    }
195	
196	    /**
197	     * Counts the owners that already exist (before the current create) whose first and last names
198	     * both match the supplied names, compared case-insensitively. The returned value is captured on
199	     * the new owner at creation time and does not change as further owners are added later.
200	     *
201	     * @param firstName the new owner's first name
202	     * @param lastName  the new owner's last name
203	     * @return the number of pre-existing namesake owners
204	     */
205	    private int namesakeCount(String firstName, String lastName) {
206	        return (int) this.clinicService.findAllOwners().stream()
207	            .filter(existing -> existing.getFirstName() != null
208	                && existing.getFirstName().equalsIgnoreCase(firstName)
209	                && existing.getLastName() != null
210	                && existing.getLastName().equalsIgnoreCase(lastName))
211	            .count();
212	    }
213	
214	    /**
215	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where
216	     * {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3} is the
217	     * upper-cased first three letters of the last name, and {@code NNNN} is a per-city 4-digit
218	     * zero-padded sequence equal to one more than the number of owners already in that city
219	     * (e.g. {@code 'SYD-SMI-0007'}).
220	     *
221	     * @param city     the owner's city
222	     * @param lastName the owner's last name
223	     * @return the assigned customer code
224	     */
225	    private String nextCustomerCode(String city, String lastName) {
226	        String cityPrefix = first3Upper(city);
227	        String lastPrefix = first3Upper(lastName);
228	        String cityKey = normalizeForHousehold(city);
229	        long sequence = this.clinicService.findAllOwners().stream()
230	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
231	            .count() + 1L;
232	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
233	    }
234	
235	    /**
236	     * Returns the upper-cased first three characters of {@code value}, or fewer if the value is
237	     * shorter. A {@code null} value yields the empty string.
238	     *
239	     * @param value the source value
240	     * @return the upper-cased first three characters
241	     */
242	    private String first3Upper(String value) {
243	        String v = (value == null ? "" : value);
244	        return v.substring(0, Math.min(3, v.length())).toUpperCase(java.util.Locale.ROOT);
245	    }
246	
247	    /**
248	     * Normalizes a street address applied whenever an owner is created: leading and trailing
249	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
250	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
251	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
252	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
253	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
254	     * {@code '12 MAIN STREET'}.
255	     *
256	     * @param address the raw address as submitted, or {@code null} when absent
257	     * @return the normalized address, or the empty string when the value is blank
258	     */
259	    private String normalizeAddress(String address) {
260	        String collapsed = (address == null ? "" : address)
261	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
262	        if (collapsed.isEmpty()) {
263	            return "";
264	        }
265	        String[] tokens = collapsed.split(" ");
266	        for (int i = 0; i < tokens.length; i++) {
267	            switch (tokens[i]) {
268	                case "ST" -> tokens[i] = "STREET";
269	                case "RD" -> tokens[i] = "ROAD";
270	                case "AVE" -> tokens[i] = "AVENUE";
271	                default -> { }
272	            }
273	        }
274	        return String.join(" ", tokens);
275	    }
276	
277	    /**
278	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
279	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
280	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
281	     * empty string.
282	     *
283	     * @param value the raw value (last name or address) as submitted
284	     * @return the normalized comparison key
285	     */
286	    private String normalizeForHousehold(String value) {
287	        if (value == null) {
288	            return "";
289	        }
290	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
291	    }
292	
293	    /**
294	     * Derives the stable shared household identifier for a household, keyed on the normalized last
295	     * name and address. Because it is a pure function of those normalized keys, every owner in the
296	     * same household deterministically computes the same value. The identifier is the first 12
297	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
298	     * (the separator prevents distinct name/address pairs from colliding).
299	     *
300	     * @param lastNameKey the normalized last-name comparison key
301	     * @param addressKey  the normalized address comparison key
302	     * @return the stable household identifier
303	     */
304	    private String householdId(String lastNameKey, String addressKey) {
305	        String seed = lastNameKey + "�" + addressKey;
306	        try {
307	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
308	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
309	            StringBuilder sb = new StringBuilder(digest.length * 2);
310	            for (byte b : digest) {
311	                sb.append(String.format("%02x", b));
312	            }
313	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
314	        }
315	        catch (java.security.NoSuchAlgorithmException e) {
316	            throw new IllegalStateException("SHA-256 not available", e);
317	        }
318	    }
319	
320	    /**
321	     * The exact number of national (subscriber) digits required for a given country calling code,
322	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
323	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
324	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
325	     */
326	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
327	        java.util.Map.of("61", 9, "1", 10);
328	
329	    /**
330	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
331	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
332	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
333	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
334	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
335	     * is stored as {@code '+61412345678'}.
336	     *
337	     * <p>In addition, when the number's country code has a fixed national-number length (see
338	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
339	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
340	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
341	     *
342	     * @param telephone the raw telephone number as submitted
343	     * @return the normalized E.164 telephone number
344	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
345	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
346	     *         for its country code
347	     */
348	    private String normalizeTelephone(String telephone) {
349	        String raw = telephone == null ? "" : telephone.trim();
350	        String digits = raw.replaceAll("\\D", "");
351	        String e164;
352	        if (raw.startsWith("+")) {
353	            e164 = "+" + digits;
354	        } else {
355	            if (digits.startsWith("0")) {
356	                digits = digits.substring(1);
357	            }
358	            e164 = "+61" + digits;
359	        }
360	        int digitCount = e164.length() - 1;
361	        if (digitCount < 8 || digitCount > 15) {
362	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
363	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
364	        }
365	        validateNationalNumberLength(e164);
366	        return e164;
367	    }
368	
369	    /**
370	     * Validates that an E.164 number's national-number length is correct for its country code.
371	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
372	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
373	     * following it must match exactly. Country codes without a fixed length are left unchecked.
374	     *
375	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
376	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
377	     *         for the country code
378	     */
379	    private void validateNationalNumberLength(String e164) {
380	        String allDigits = e164.substring(1);
381	        String bestCode = null;
382	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
383	            if (allDigits.startsWith(code)
384	                    && (bestCode == null || code.length() > bestCode.length())) {
385	                bestCode = code;
386	            }
387	        }
388	        if (bestCode == null) {
389	            return;
390	        }
391	        int nationalLength = allDigits.length() - bestCode.length();
392	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
393	        if (nationalLength != required) {
394	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
395	                "Telephone for country code '+" + bestCode + "' must have " + required
396	                    + " national digits");
397	        }
398	    }
399	
400	    /**
401	     * The inclusive 4-digit postcode range permitted for each canonical region, keyed by the
402	     * region derived from the owner's city ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
403	     * {@code Brisbane -> QLD}): NSW {@code 2000-2099}, VIC {@code 3000-3099}, QLD
404	     * {@code 4000-4099}. A city whose region is not listed here accepts any 4-digit postcode.
405	     */
406	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
407	        "NSW", new int[] {2000, 2099},
408	        "VIC", new int[] {3000, 3099},
409	        "QLD", new int[] {4000, 4099});
410	
411	    /**
412	     * Validates an owner's optional postcode against their city's region. The postcode is only
413	     * checked when present (a {@code null} postcode is accepted, keeping the request contract
414	     * backward-compatible). Its four-digit shape is already enforced by Bean Validation on the
415	     * request DTO. When the city maps to a known region (see {@link #REGION_POSTCODE_RANGES}) the
416	     * postcode must fall within that region's inclusive range; a city with no known region accepts
417	     * any 4-digit postcode.
418	     *
419	     * @param postcode the owner's postcode as submitted, or {@code null} when absent
420	     * @param city     the owner's city, used to derive the region whose range applies
421	     * @throws ResponseStatusException with a 400 status when a supplied postcode is out of range
422	     *         for the city's region
423	     */
424	    private void validatePostcode(String postcode, String city) {
425	        if (postcode == null) {
426	            return;
427	        }
428	        String region = org.springframework.samples.petclinic.mapper.Localities.forCity(city);
429	        int[] range = REGION_POSTCODE_RANGES.get(region);
430	        if (range == null) {
431	            return;
432	        }
433	        int value = Integer.parseInt(postcode);
434	        if (value < range[0] || value > range[1]) {
435	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
436	                "Postcode " + postcode + " is not valid for region " + region);
437	        }
438	    }
439	
440	    /**
441	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
442	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
443	     * (absent) or already valid.
444	     *
445	     * @param email the email address as submitted, or {@code null} when absent
446	     * @return the lower-cased email, or {@code null} when absent
447	     */
448	    private String normalizeEmail(String email) {
449	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
450	    }
451	
452	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
453	    @Override
454	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
455	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
456	        if (currentOwner == null) {
457	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
458	        }
459	        currentOwner.setAddress(ownerFieldsDto.getAddress());
460	        currentOwner.setCity(ownerFieldsDto.getCity());
461	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
462	        currentOwner.setLastName(ownerFieldsDto.getLastName());
463	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
464	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
465	        this.clinicService.saveOwner(currentOwner);
466	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
467	    }
468	
469	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
470	    @Transactional
471	    @Override
472	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
473	        Owner owner = this.clinicService.findOwnerById(ownerId);
474	        if (owner == null) {
475	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
476	        }
477	        this.clinicService.deleteOwner(owner);
478	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
479	    }
480	
481	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
482	    @Override
483	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
484	        Owner owner = this.clinicService.findOwnerById(ownerId);
485	        if (owner == null) {
486	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
487	        }
488	        HttpHeaders headers = new HttpHeaders();
489	        Pet pet = petMapper.toPet(petFieldsDto);
490	        owner.setId(ownerId);
491	        pet.setOwner(owner);
492	        pet.getType().setName(null);
493	        this.clinicService.savePet(pet);
494	        PetDto petDto = petMapper.toPetDto(pet);
495	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
496	            .buildAndExpand(pet.getId()).toUri());
497	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
498	    }
499	
500	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
501	    @Override
502	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
503	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
504	        if (currentOwner != null) {
505	            Pet currentPet = this.clinicService.findPetById(petId);
506	            if (currentPet != null) {
507	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
508	                currentPet.setName(petFieldsDto.getName());
509	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
510	                this.clinicService.savePet(currentPet);
511	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
512	            }
513	        }
514	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
515	    }
516	
517	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
518	    @Override
519	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
520	        HttpHeaders headers = new HttpHeaders();
521	        Visit visit = visitMapper.toVisit(visitFieldsDto);
522	        Pet pet = new Pet();
523	        pet.setId(petId);
524	        visit.setPet(pet);
525	        this.clinicService.saveVisit(visit);
526	        VisitDto visitDto = visitMapper.toVisitDto(visit);
527	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
528	            .buildAndExpand(visit.getId()).toUri());
529	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
530	    }
531	
532	
533	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
534	    @Override
535	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
536	        Owner owner = this.clinicService.findOwnerById(ownerId);
537	        if (owner != null) {
538	            Pet pet = owner.getPet(petId);
539	            if (pet != null) {
540	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
541	            }
542	        }
